class DrugService:
    @staticmethod
    def get_drug(code: str) -> Optional[DrugItem]:
        return DRUG_DATABASE.get(code.strip())

    @staticmethod
    def search(query: str) -> List[DrugItem]:
        q = query.lower().strip()
        return [d for d in DRUG_DATABASE.values() if q in d.generic_name.lower() or q in d.brand_name.lower()][:50]
